def step(context):
    accepts = context['inputs']['accept'][0]['payload']
    scores = context['inputs']['scores'][0]['payload']
    if accepts['records'] != scores['records']:
        raise ValueError('decision tensors lost paper identity alignment')
    decisions = [{'payload': {'paper_id': row['paper_id'], 'conference_id': row['conference_id'],
        'decision': 'accept' if accepts['values'][i] >= 0.5 else 'reject',
        'final_score': scores['values'][i]}} for i,row in enumerate(accepts['records'])]
    return {'outputs': {'decisions': decisions or [{'payload': {'empty_cycle': True}}],
        'next': [{'payload': {'year': context['period']}}],
        'world': [{'payload': context['inputs']['observations'][0]['payload']}]},
        'state': {'cycles': context['state'].get('cycles', 0) + 1}}

def step(context):
    world = context['inputs']['observations'][0]['payload']
    records, values = [], []
    for conference in world['conferences']['conferences']:
        for paper in conference['submitted_papers']:
            reviews = conference['reviews'].get(paper['id'], [])
            score = sum(r['overall_score'] for r in reviews) / len(reviews) if reviews else 0.0
            records.append({'paper_id': paper['id'], 'conference_id': conference['conference_id']})
            values.append([score, len(reviews)])
    return {'outputs': {'features': [{'payload': {'values': values, 'records': records}}],
                        'world': [{'payload': world}]},
            'state': {'cycles': context['state'].get('cycles', 0) + 1}}

artifact.source:
def step(context):
    import json
    plan = context['inputs']['plans'][0]['payload']
    world = context['inputs']['world'][0]['payload']
    year = context['period']
    active = {a['id'] for a in world['ecosystem']['agents'] if a['can_author'] and a['is_active']}
    amendments = []
    for original in plan['assignments']:
        if original['actor_id'] not in active:
            continue
        assignment = json.loads(json.dumps(original))
        assignment['direction']['years'] = 1
        assignment['project_start_year'] = year
        assignment['project_end_year'] = year
        assignment['detailed_focus'] = original['detailed_focus'] + ' Annual scope: produce a complete, narrow native manuscript this year; retain the chosen topic and original evidence.'
        assignment['reason'] = original['reason'] + ' Institution schedules an annual publication window.'
        amendments.append({'payload':{'schema':'native-research-amendment-v1','target_year':year,
            'assignment':assignment,'submit':True}})
    return {'outputs':{'amendments':amendments},'state':{'cycles':context['state'].get('cycles',0)+1,
        'last_year':year,'scheduled_actor_ids':sorted(active)}}

